registerTool({
  id: "rot13",
  description: "ROT13-encode a text string (rotates ASCII letters a-z a 13 positions, preserving case; non-letters unchanged).",
  parameters: {
    type: "object",
    properties: { text: { type: "string", description: "The text to ROT13-encode" } },
    required: ["text"]
  },
  execute: async (args) => ({
    output: (args.text || "").replace(/[a-zA-Z]/g, c =>
      String.fromCharCode(c.charCodeAt(0) + (c.toLowerCase() <= "m" ? 13 : -13))
    )
  })
});
"registered"

const tools = await plugins.get('rc5-tools').next();
const t = tools.value.find(x => x.id === 'rot13');
if (!t) return 'NOT FOUND';
const r = await t.execute({ text: 'Lopecode' });
return 'registry ids: ' + tools.value.map(x => x.id).join(', ') + ' | rot13("Lopecode") = ' + r.output;

const list = toolsView.value || [];
const t = list.find(x => x && x.id === 'rot13');
if (!t) return 'rot13 NOT FOUND in registry';
const r = await t.execute({ text: 'Lopecode' });
return 'rot13 tool found in registry; execute("Lopecode") => ' + JSON.stringify(r);

